using System.Text;
namespace SystemKnowledgeHub.Api.DeveloperSupport.Demo;
internal static class DemoAssets
{
    public static byte[] Png() => Convert.FromBase64String("");
    public static byte[] Pdf()
    {
        var text = "BT /F1 18 Tf 50 760 Td (System Knowledge Hub - DEMO SOP) Tj 0 -35 Td /F1 12 Tf (Lot Track In: check Equipment, Hold and STATE_FLAG.) Tj 0 -24 Td (Synthetic reference only. No production instructions.) Tj ET";
        var objects = new[] { "<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Kids [3 0 R] /Count 1 >>", "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>", "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>", $"<< /Length {Encoding.ASCII.GetByteCount(text)} >>\nstream\n{text}\nendstream" };
        var builder = new StringBuilder("%PDF-1.4\n"); var offsets = new List<int> { 0 };
        for (var i = 0; i < objects.Length; i++) { offsets.Add(builder.Length); builder.Append($"{i + 1} 0 obj\n{objects[i]}\nendobj\n"); }
        var start = builder.Length; builder.Append("xref\n0 6\n0000000000 65535 f \n"); foreach (var offset in offsets.Skip(1)) builder.Append($"{offset:D10} 00000 n \n");
        builder.Append($"trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n{start}\n%%EOF\n"); return Encoding.ASCII.GetBytes(builder.ToString());
    }
}
